import React from 'react';
import {  Send, CheckCircle, Clock } from 'lucide-react';

const StudentDashboard = () => {
  return (
    <div className="p-8 text-right" dir="rtl">
      <h1 className="text-2xl font-bold mb-8">لوحة التحكم</h1>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
          <div><p className="text-slate-500 text-sm">طلبات مرسلة</p><p className="text-2xl font-bold">12</p></div>
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl"><Send size={24}/></div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
          <div><p className="text-slate-500 text-sm">قيد الانتظار</p><p className="text-2xl font-bold">4</p></div>
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><Clock size={24}/></div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
          <div><p className="text-slate-500 text-sm">تم القبول</p><p className="text-2xl font-bold">2</p></div>
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><CheckCircle size={24}/></div>
        </div>
      </div>
    </div>
  );
};
export default StudentDashboard;
